Editing record or classification tree permissions on a classification

Editing download permissions on a classification

```http
PUT /classification/8735a5a3e75a4bc0a2a1a3cd0069b669/{recordpermissions|classificationtreepermissions}
{
	"breakInheritance":false,
	"permissions": {
		"addOrUpdate": [
			{
					"userGroupId":"21d41eb183234b0cbe7b6a9c898b1de1",
					"accessRight":"Read"
			},
			{
					"userGroupId":"21d41eb183234b0cbe7b6a9c898b1de1",
					"accessRight":"FullControl"
			}
		],
		"remove": [
			{
					"userGroupId":"21d41eb183234b0cbe7b6a9c898b1de1"
			}
		]
	}
}
```

```http
PUT /classification/8735a5a3e75a4bc0a2a1a3cd0069b669/downloadpermissions
{
	"breakInheritance":false,
	"permissions": {
		"addOrUpdate": [
			{
					"userGroupId":"e688500cc109488f959da82b0093014a",
					"accessRight":"Allow"
			}
		],
		"remove": [
			{
					"userGroupId": "0cb08fb798d74d369e75e017350f8378"
			}
		]
	}
}
```

